import{F as t}from"./chunks/FigureContainer.BTAjxbcw.js";import{H as e}from"./chunks/HighLightText.DEA09ZsT.js";import{c as r,o,a,d as l,b as p,e as n,w as i}from"./chunks/vitepress-theme-teek.Cn3pDl2f.js";/* empty css                                                                               *//* empty css                                                             */const b={class:"tip custom-block"},T=JSON.parse('{"title":"推理与解码策略","description":"系统拆解 LLM 推理时的核心解码策略：贪心解码与 Beam Search 的确定性路线、Top-k 与 Top-p 采样的随机性控制、温度系数对概率分布的调节机制，以及对比搜索等混合策略的设计思路与选型参考。","frontmatter":{"title":"推理与解码策略","tldr":"贪心求稳，Beam Search 求质，温度系数求活——解码策略是 LLM Token 选择的决策算法。","description":"系统拆解 LLM 推理时的核心解码策略：贪心解码与 Beam Search 的确定性路线、Top-k 与 Top-p 采样的随机性控制、温度系数对概率分布的调节机制，以及对比搜索等混合策略的设计思路与选型参考。","tags":["概念","推理","解码策略","温度系数","Top-p"],"categories":["大模型基础","推理与生成"],"date":"2026-06-29T09:50:23.000Z","permalink":"/llm-basic/inference-decoding-strategies"},"headers":[],"relativePath":"llm-basic/inference-decoding-strategies.md","filePath":"22.大模型基础/04.推理与生成/01.推理与解码策略.md"}'),c={name:"llm-basic/inference-decoding-strategies.md"},f=Object.assign(c,{setup(u){return(d,s)=>(o(),r("div",null,[s[20]||(s[20]=a("h1",{id:"推理与解码策略",tabindex:"-1"},[n("推理与解码策略 "),a("a",{class:"header-anchor",href:"#推理与解码策略","aria-label":"Permalink to “推理与解码策略”"},"​")],-1)),s[21]||(s[21]=a("blockquote",null,[a("p",null,[a("strong",null,"摘要"),n(": 大语言模型在生成文本时，每一步都是从整个词表中选出下一个最合适的 token，而解码策略决定了这道选择题的求解方式。贪心解码永远选择概率最高的 token，效率高但容易陷入重复；Beam Search 维护多条候选序列，在翻译等确定性任务中表现优异，但会牺牲生成多样性。Top-k 与 Top-p（核采样）通过限制候选集大小引入可控随机性，温度系数则在 Softmax 之前缩放 logits 以调节概率分布的陡峭程度。本文从机制原理、适用场景和参数调优三个维度对比了各策略的优劣，并介绍了结合多种策略优势的对比搜索（Contrastive Search）等混合方案，为不同应用场景下的解码策略选型提供参考框架。")])],-1)),s[22]||(s[22]=a("h2",{id:"_1-引言",tabindex:"-1"},[n("1. 引言 "),a("a",{class:"header-anchor",href:"#_1-引言","aria-label":"Permalink to “1. 引言”"},"​")],-1)),s[23]||(s[23]=a("p",null,[n("在前面的文章中，我们已经了解了模型如何被训练出来。但模型训练完成后，还有一个关键问题："),a("strong",null,'给定一个已经训练好的模型，它如何"写出"一个个 token？'),n(" 这就是推理与解码策略要解决的问题。")],-1)),a("p",null,[s[1]||(s[1]=n("一个 LLM 在生成文本时，每一步实际上是在做一道选择题：",-1)),p(e,{bold:"",type:"info"},{default:i(()=>[...s[0]||(s[0]=[n("给定当前的上下文，从整个词表（词汇量通常 5 万到 20 万）中选出下一个最合适的 token",-1)])]),_:1}),s[2]||(s[2]=n("。",-1))]),s[24]||(s[24]=l(`<p><strong>解码策略决定了这道选择题怎么做</strong>——是永远选最确定的那个，还是偶尔冒险尝试一些可能性？</p><h2 id="_2-解码策略" tabindex="-1">2. 解码策略 <a class="header-anchor" href="#_2-解码策略" aria-label="Permalink to “2. 解码策略”">​</a></h2><h3 id="_2-1-greedy-decoding-贪心解码" tabindex="-1">2.1 Greedy Decoding（贪心解码） <a class="header-anchor" href="#_2-1-greedy-decoding-贪心解码" aria-label="Permalink to “2.1 Greedy Decoding（贪心解码）”">​</a></h3><p>贪心解码是最简单直观的策略：<strong>每一步都选择概率最高的那个 token</strong>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>时间步 1: &quot;我&quot; → 模型计算 → {的: 0.3, 想: 0.25, 要: 0.15, ...}</span></span>
<span class="line"><span>         → 选 &quot;的&quot; (概率最高)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>时间步 2: &quot;我的&quot; → 模型计算 → {天: 0.4, 猫: 0.2, ...}</span></span>
<span class="line"><span>         → 选 &quot;天&quot; (概率最高)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>时间步 3: &quot;我的天&quot; → ... 最终输出：&quot;我的天哪！太棒了！&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>优点</strong>：速度极快，每一步只做一次 argmax 操作。</p><p><strong>缺点</strong>：</p><ul><li><strong>确定性太强</strong>：同一个输入永远产生同一个输出，缺乏多样性</li><li><strong>容易陷入重复循环</strong>：一旦模型进入一个高频短语模式，可能不断重复同一句话</li><li><strong>没有全局最优保证</strong>：贪心算法在每一步选局部最优，未必得到整体最优序列</li></ul><p><strong>直观类比</strong>：贪心解码就像一个在迷宫里永远走&quot;看起来最近的路&quot;的人——每一步都是局部最优，但很可能走进死胡同。</p><h3 id="_2-2-beam-search-束搜索" tabindex="-1">2.2 Beam Search（束搜索） <a class="header-anchor" href="#_2-2-beam-search-束搜索" aria-label="Permalink to “2.2 Beam Search（束搜索）”">​</a></h3><p>束搜索是贪心解码的升级版：<strong>每步保留 k 个最有可能的候选序列，而不是只保留 1 个</strong>。k 称为 beam width（束宽）。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>beam_width = 2 的示例：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>时间步 1: 模型评估所有可能的第一个 token</span></span>
<span class="line"><span>        候选序列:</span></span>
<span class="line"><span>          [&quot;我&quot;]  score = -0.5</span></span>
<span class="line"><span>          [&quot;今&quot;]  score = -1.2</span></span>
<span class="line"><span>        保留 Top-2：[&quot;我&quot;, -0.5], [&quot;今&quot;, -1.2]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>时间步 2: 对每个候选序列，尝试所有可能的下一个 token</span></span>
<span class="line"><span>        [&quot;我&quot;] + &quot;的&quot; → score = -0.5 + (-0.3) = -0.8</span></span>
<span class="line"><span>        [&quot;我&quot;] + &quot;想&quot; → score = -0.5 + (-0.4) = -0.9</span></span>
<span class="line"><span>        [&quot;今&quot;] + &quot;天&quot; → score = -1.2 + (-0.2) = -1.4</span></span>
<span class="line"><span>        [&quot;今&quot;] + &quot;晚&quot; → score = -1.2 + (-0.5) = -1.7</span></span>
<span class="line"><span>        保留 Top-2：[&quot;我的&quot;, -0.8], [&quot;我想&quot;, -0.9]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>时间步 3: ... 继续扩展，始终只保留分数最高的 2 条路径</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p><strong>束宽的影响</strong>：</p><table tabindex="0"><thead><tr><th>beam_width</th><th>行为特点</th><th>适用场景</th></tr></thead><tbody><tr><td>1</td><td>等价于贪心解码</td><td>不需要</td></tr><tr><td>3-5</td><td>在速度与质量间取得平衡</td><td>翻译、摘要</td></tr><tr><td>10-20</td><td>更优的全局序列</td><td>高精度翻译</td></tr><tr><td>50+</td><td>几乎等于穷举搜索</td><td>极少使用</td></tr></tbody></table><p><strong>优点</strong>：比贪心解码更可能找到全局更优的序列，在翻译等需要精确输出的任务上效果显著。</p><p><strong>缺点</strong>：</p><ul><li><strong>计算量翻倍</strong>：beam_width=5 意味着每一步的计算量是贪心的 5 倍</li><li><strong>开放性生成表现差</strong>：束搜索倾向于产生&quot;安全&quot;的文本，缺乏惊喜和创造力。在对话和创意写作中远不如采样策略</li></ul><h3 id="_2-3-top-k-采样" tabindex="-1">2.3 Top-k 采样 <a class="header-anchor" href="#_2-3-top-k-采样" aria-label="Permalink to “2.3 Top-k 采样”">​</a></h3>`,18)),a("p",null,[s[4]||(s[4]=n("Top-k 采样的思路：",-1)),p(e,{bold:"",type:"info"},{default:i(()=>[...s[3]||(s[3]=[n("只从概率最高的 k 个候选 token 中随机采样，切断长尾的低概率 token",-1)])]),_:1}),s[5]||(s[5]=n("。",-1))]),s[25]||(s[25]=l(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>原始概率分布（假设词表大小 50000）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;好的&quot;  ████████████████████  0.40</span></span>
<span class="line"><span>  &quot;可以&quot;  ██████████            0.20</span></span>
<span class="line"><span>  &quot;没问题&quot; ██████               0.12</span></span>
<span class="line"><span>  &quot;行&quot;    ████                 0.08</span></span>
<span class="line"><span>  &quot;嗯&quot;    ███                  0.06</span></span>
<span class="line"><span>  &quot;OK&quot;    ██                   0.05</span></span>
<span class="line"><span>  &quot;好滴&quot;  ██                   0.04</span></span>
<span class="line"><span>  ... (49993 个低概率 token) ...</span></span>
<span class="line"><span>  &quot;旮旯&quot;  ▏                    0.00001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Top-k (k=6): 只从前 6 个候选里按概率采样</span></span>
<span class="line"><span>  → 重归一化后：&quot;好的&quot; 44%, &quot;可以&quot; 22%, &quot;没问题&quot; 13%, &quot;行&quot; 9%, &quot;嗯&quot; 7%, &quot;OK&quot; 5%</span></span>
<span class="line"><span>  → 从这 6 个中随机抽取一个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么需要 Top-k？</p><p>原始词表中大部分 token 在当前语境下完全不合理（比如对话中突然出现&quot;旮旯&quot;）。Top-k 剪掉了这些&quot;噪音&quot;，让模型在合理的候选集中产生多样性。</p><p><strong>注意事项</strong>：固定的 k 值对于不同语境不够灵活。一个很确定的上下文（如 &quot;法国的首都是&quot;）可能只有 2-3 个合理 token，而一个开放的上下文（如 &quot;我认为&quot;）可能有 50+ 个合理选择。固定 k=50 可能在前者引入噪音，在后者限制创造力。</p></div><h3 id="_2-4-top-p-nucleus-sampling-核采样" tabindex="-1">2.4 Top-p（Nucleus Sampling，核采样） <a class="header-anchor" href="#_2-4-top-p-nucleus-sampling-核采样" aria-label="Permalink to “2.4 Top-p（Nucleus Sampling，核采样）”">​</a></h3>`,3)),a("p",null,[s[7]||(s[7]=n("Top-p 采样解决了 Top-k 固定候选数不够灵活的问题：",-1)),p(e,{bold:"",type:"info"},{default:i(()=>[...s[6]||(s[6]=[n("不是固定取 k 个，而是动态选取累计概率达到阈值 p 的最小候选集",-1)])]),_:1}),s[8]||(s[8]=n("。",-1))]),s[26]||(s[26]=l(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Top-p (p=0.9) 的工作方式：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  概率分布（从高到低排序）：</span></span>
<span class="line"><span>  &quot;好的&quot;      0.40  ← 纳入，累计 0.40</span></span>
<span class="line"><span>  &quot;可以&quot;      0.25  ← 纳入，累计 0.65</span></span>
<span class="line"><span>  &quot;没问题&quot;    0.12  ← 纳入，累计 0.77</span></span>
<span class="line"><span>  &quot;行&quot;        0.08  ← 纳入，累计 0.85</span></span>
<span class="line"><span>  &quot;嗯&quot;        0.06  ← 纳入，累计 0.91  ← 累计超过 0.9，停止</span></span>
<span class="line"><span>  -------- 阈值 ----------</span></span>
<span class="line"><span>  &quot;OK&quot;        0.04  ← 丢弃</span></span>
<span class="line"><span>  &quot;好滴&quot;      0.03  ← 丢弃</span></span>
<span class="line"><span>  ... 其余全部丢弃 ...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  在入围的 5 个 token 中按原概率重归一化后采样</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">直观类比</p><p>想象你在点外卖：</p><ul><li>Top-k 是说&quot;只看评分前 20 的餐厅&quot;；</li><li>Top-p 是说&quot;只考虑能覆盖 90% 好评的餐厅&quot;；</li></ul><p>后者的候选集大小会根据地区（语境）自动调整——美食街可能有 50 家入围，偏远地区可能只有 3 家。</p></div><p><strong>p 值的调参指南</strong>：</p><table tabindex="0"><thead><tr><th>p 值</th><th>效果</th><th>适用</th></tr></thead><tbody><tr><td>0.9-1.0</td><td><strong>高多样性，更有创意</strong></td><td><strong>创意写作、头脑风暴</strong></td></tr><tr><td>0.7-0.9</td><td><strong>平衡</strong></td><td><strong>通用对话</strong></td></tr><tr><td>0.5-0.7</td><td><strong>更保守，更确定</strong></td><td><strong>事实性问答、代码生成</strong></td></tr></tbody></table>`,4)),a("p",null,[s[10]||(s[10]=n("现代 LLM 推理中，",-1)),s[11]||(s[11]=a("strong",null,"Top-p + Top-k 经常联用",-1)),s[12]||(s[12]=n("：",-1)),p(e,{bold:"",type:"note"},{default:i(()=>[...s[9]||(s[9]=[n("先用 Top-k 粗筛，再用 Top-p 精筛",-1)])]),_:1}),s[13]||(s[13]=n("。",-1))]),s[27]||(s[27]=a("h3",{id:"_2-5-temperature-温度系数",tabindex:"-1"},[n("2.5 Temperature（温度系数） "),a("a",{class:"header-anchor",href:"#_2-5-temperature-温度系数","aria-label":"Permalink to “2.5 Temperature（温度系数）”"},"​")],-1)),s[28]||(s[28]=a("p",null,[n("Temperature 不是一种独立的采样策略，而是对概率分布的一个"),a("strong",null,"预处理变换"),n("。它在 softmax 之前对 logits 进行缩放，公式为：")],-1)),p(t,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/tempature_compute.png",caption:""}),s[29]||(s[29]=l(`<p><strong>缩放后的实际效果——以一组具体数值演示</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>假设模型对下一个 token 的 Logits 为：</span></span>
<span class="line"><span>  A: 5.0</span></span>
<span class="line"><span>  B: 2.0</span></span>
<span class="line"><span>  C: 1.0</span></span>
<span class="line"><span>  D: 0.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T = 0.5（低温）：</span></span>
<span class="line"><span>  Logits ÷ 0.5 → [10.0, 4.0, 2.0, 0.0]</span></span>
<span class="line"><span>  Softmax       → [0.982, 0.018, 0.000, 0.000]</span></span>
<span class="line"><span>  → A 几乎独占所有概率（98.2%），其他 token 基本没机会被选中</span></span>
<span class="line"><span>  → 模型极度保守，几乎等价于每次都选 A</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T = 1.0（标准温度）：</span></span>
<span class="line"><span>  Logits ÷ 1.0 → [5.0, 2.0, 1.0, 0.0]</span></span>
<span class="line"><span>  Softmax       → [0.936, 0.047, 0.017, 0.006]</span></span>
<span class="line"><span>  → A 仍然主导，但 B 有 4.7% 的概率偶尔被选中</span></span>
<span class="line"><span>  → 保持原始分布的自然比例</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T = 2.0（高温）：</span></span>
<span class="line"><span>  Logits ÷ 2.0 → [2.5, 1.0, 0.5, 0.0]</span></span>
<span class="line"><span>  Softmax       → [0.794, 0.134, 0.073, 0.033]</span></span>
<span class="line"><span>  → A 的概率从 93.6% 降到 79.4%，B 从 4.7% 升到 13.4%</span></span>
<span class="line"><span>  → 分布显著平坦化，低分 token 也有可观机会被选中</span></span>
<span class="line"><span>  → 输出更多样、更有创意（但也更容易跑偏）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p><strong>缩放到底改变了什么？</strong></p><p>T &lt; 1 时，Logits 的差异被<strong>放大</strong>——原本相差 3 分（A:5 vs B:2），除以 0.5 后差 6 分（10 vs 4），Softmax 的指数函数再进一步放大这个差距，最终概率极度集中。</p><p>T &gt; 1 时，Logits 的差异被<strong>压缩</strong>——原本差 3 分，除以 2 后只差 1.5 分（2.5 vs 1.0），高分 token 的优势被削弱，低分 token 浮出水面。</p><p><strong>极限情况</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>T → 0:  概率分布极端尖锐 → 几乎等价于贪心解码（每次都选最高分）</span></span>
<span class="line"><span>T = 1:  原始概率分布（不做改变）</span></span>
<span class="line"><span>T → ∞:  概率分布趋于均匀 → 完全随机生成（每个 token 概率基本相同）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>不同温度的直观效果</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Prompt: &quot;今天天气真&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T=0 (贪婪):   &quot;今天天气真好！阳光明媚，万里无云。&quot;          ← 最确定性输出</span></span>
<span class="line"><span>T=0.3:        &quot;今天天气真好！适合出去走走。&quot;                 ← 比较确定</span></span>
<span class="line"><span>T=0.7:        &quot;今天天气真不错，不如去公园散步吧。&quot;             ← 适度多样</span></span>
<span class="line"><span>T=1.0:        &quot;今天天气真适合喝一杯热咖啡然后躺在沙发上看书。&quot;  ← 有创意</span></span>
<span class="line"><span>T=1.5:        &quot;今天天气真相是某种不可言说的隐喻。&quot;             ← 开始离谱</span></span>
<span class="line"><span>T=2.0:        &quot;今天天气真旮旯三才图会...&quot;                    ← 完全随机</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>最佳实践</strong>：</p><ul><li><strong>代码生成、数学推理</strong>：T=0 或接近 0，需要精确</li><li><strong>日常对话</strong>：T=0.5-0.8，自然且有变化</li><li><strong>创意写作</strong>：T=1.0-1.3，需要想象力</li><li><strong>T&gt;1.5</strong>：通常不推荐，输出质量急剧下降</li></ul><h2 id="_3-logits-logprobs" tabindex="-1">3. Logits / Logprobs <a class="header-anchor" href="#_3-logits-logprobs" aria-label="Permalink to “3. Logits / Logprobs”">​</a></h2><h3 id="_3-1-从-logits-到概率" tabindex="-1">3.1 从 Logits 到概率 <a class="header-anchor" href="#_3-1-从-logits-到概率" aria-label="Permalink to “3.1 从 Logits 到概率”">​</a></h3><p>理解 logits 和 logprobs 是理解 LLM 内部运作的关键一步。模型最后一层（LM Head）输出的原始数值叫 <strong>logits</strong>，它们还需要经过一系列变换才能变成概率：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>模型的原始输出                 经过变换                      最终结果</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Logits (未归一化分数)  →  Softmax →  概率分布  →  log →  Logprobs (对数概率)</span></span>
<span class="line"><span>[2.3, 1.1, -0.5, ...]    ↓            [0.58, 0.17, 0.03, ...]</span></span>
<span class="line"><span>                          每个 logit     概率之和 = 1</span></span>
<span class="line"><span>                          先做 exp(e^z_i)</span></span>
<span class="line"><span>                          再做归一化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>具体计算：</span></span>
<span class="line"><span>  z = [2.3, 1.1, -0.5]</span></span>
<span class="line"><span>  e^z = [9.97, 3.00, 0.61]</span></span>
<span class="line"><span>  sum = 9.97 + 3.00 + 0.61 = 13.58</span></span>
<span class="line"><span>  softmax = [9.97/13.58, 3.00/13.58, 0.61/13.58]</span></span>
<span class="line"><span>          = [0.734, 0.221, 0.045]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  logprobs = log([0.734, 0.221, 0.045])</span></span>
<span class="line"><span>           = [-0.309, -1.510, -3.101]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">为什么用对数概率？</p><ol><li><strong>数值稳定性</strong>：概率相乘很容易变成极小的浮点数（下溢），对数把乘法变加法</li><li><strong>与损失函数一致</strong>：训练时用的交叉熵损失本质上就是负对数概率</li><li><strong>更直观的比较</strong>：logprob=-2 比 logprob=-5 的概率大约高 20 倍 (e^3)</li></ol></div><h3 id="_3-2-logprobs-的应用" tabindex="-1">3.2 Logprobs 的应用 <a class="header-anchor" href="#_3-2-logprobs-的应用" aria-label="Permalink to “3.2 Logprobs 的应用”">​</a></h3><h4 id="应用一-置信度评估" tabindex="-1">应用一：置信度评估 <a class="header-anchor" href="#应用一-置信度评估" aria-label="Permalink to “应用一：置信度评估”">​</a></h4><p>通过 token 级别的 logprobs 可以判断模型对自己输出的&quot;把握&quot;有多大：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>场景：用户问&quot;法国的首都是什么？&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出序列及 logprobs：</span></span>
<span class="line"><span>  &quot;巴黎&quot;  logprob = -0.1   ← 非常确定</span></span>
<span class="line"><span>  &quot;是&quot;    logprob = -0.05  ← 非常确定</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  → 模型对此答案非常有信心，可以高置信度使用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出序列及 logprobs：</span></span>
<span class="line"><span>  &quot;让我想想...&quot;  logprob = -2.3  ← 不太确定</span></span>
<span class="line"><span>  &quot;可能是巴黎&quot;   logprob = -3.1  ← 很不确定</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  → 模型在犹豫，这个答案可能需要人工复核</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h4 id="应用二-模型路由选择" tabindex="-1">应用二：模型路由选择 <a class="header-anchor" href="#应用二-模型路由选择" aria-label="Permalink to “应用二：模型路由选择”">​</a></h4><p>在混合专家路由或级联推理架构中，可以用 logprobs 决定是否需要调用更强的模型：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>低成本模型 → 生成答案 + logprobs</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─ 平均 logprob &gt; -1.0（高置信度）→ 直接返回答案</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─ 平均 logprob &lt; -1.0（低置信度）→ 调用更强模型重新生成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="应用三-幻觉检测" tabindex="-1">应用三：幻觉检测 <a class="header-anchor" href="#应用三-幻觉检测" aria-label="Permalink to “应用三：幻觉检测”">​</a></h4><p>当模型生成某个事实时，如果相关 token 的 logprobs 异常低（模型自己都不确定），可能是幻觉信号。</p><h2 id="_4-kv-cache" tabindex="-1">4. KV Cache <a class="header-anchor" href="#_4-kv-cache" aria-label="Permalink to “4. KV Cache”">​</a></h2><h3 id="_4-1-问题的起源" tabindex="-1">4.1 问题的起源 <a class="header-anchor" href="#_4-1-问题的起源" aria-label="Permalink to “4.1 问题的起源”">​</a></h3><p>在自回归生成中，模型每生成一个新 token，都需要重新计算<strong>所有历史 token</strong> 的注意力。</p><p>这带来了巨大的计算浪费：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>没有 KV Cache 的推理过程：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 1: 输入 [&quot;我&quot;, &quot;爱&quot;, &quot;你&quot;] → 计算 3 个 token 的 Q/K/V → 输出 token_4</span></span>
<span class="line"><span>Step 2: 输入 [&quot;我&quot;, &quot;爱&quot;, &quot;你&quot;, token_4] → 重新计算全部 4 个 token 的 Q/K/V → 输出 token_5</span></span>
<span class="line"><span>                                                        ↑</span></span>
<span class="line"><span>                                            &quot;我&quot;&quot;爱&quot;&quot;你&quot; 的 K/V 已经在 Step 1 算过了！</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div>`,30)),a("p",null,[s[15]||(s[15]=a("strong",null,"KV Cache 的核心思想",-1)),s[16]||(s[16]=n("：",-1)),p(e,{type:"note"},{default:i(()=>[...s[14]||(s[14]=[n("每一层的 Key 和 Value 矩阵一旦算出来就存下来，下次直接用，不再重复计算。",-1)])]),_:1})]),s[30]||(s[30]=l(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>      GPU 显存布局（单层 Attention ）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      ┌──────────────────────────────────────┐</span></span>
<span class="line"><span>      │             KV Cache                  │</span></span>
<span class="line"><span>      │                                       │</span></span>
<span class="line"><span>      │  token_1: [K₁₁...K₁₆₄][V₁₁...V₁₆₄]  │  ← 已缓存，直接读取</span></span>
<span class="line"><span>      │  token_2: [K₂₁...K₂₆₄][V₂₁...V₂₆₄]  │  ← 已缓存，直接读取</span></span>
<span class="line"><span>      │  token_3: [K₃₁...K₃₆₄][V₃₁...V₃₆₄]  │  ← 已缓存，直接读取</span></span>
<span class="line"><span>      │  token_4: [计算中... ][计算中...  ]   │  ← 新 token，需要计算</span></span>
<span class="line"><span>      │                                       │</span></span>
<span class="line"><span>      └──────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      新 token 的 Attention 计算：</span></span>
<span class="line"><span>      Q₄ · [K₁ K₂ K₃ K₄]ᵀ → 直接使用缓存的 K₁~K₃，只算 K₄</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div>`,1)),a("div",b,[s[18]||(s[18]=a("p",{class:"custom-block-title"},"为什么只缓存 K 和 V 而不缓存 Q？",-1)),s[19]||(s[19]=a("p",null,"因为在计算 token N 的注意力时，Q 只需要当前 token 的 Q_N，而 K 和 V 需要所有历史 token 的 K_{1..N} 和 V_{1..N}。",-1)),p(e,{type:"note",bold:""},{default:i(()=>[...s[17]||(s[17]=[n("Q 是一次性的，K 和 V 需要反复使用。",-1)])]),_:1})]),s[31]||(s[31]=l(`<h3 id="_4-2-显存占用与上下文长度的关系" tabindex="-1">4.2 显存占用与上下文长度的关系 <a class="header-anchor" href="#_4-2-显存占用与上下文长度的关系" aria-label="Permalink to “4.2 显存占用与上下文长度的关系”">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">显存（Video RAM / VRAM）：GPU 上专用于存储计算数据和中间结果的高速内存。</p><p></p><p>不同于电脑的系统内存（RAM），显存直接集成在显卡上，与 GPU 计算核心之间的数据传输带宽极高（通常 1-2 TB/s）。<strong>推理显存</strong>则特指模型在生成 token 过程中占用的显存，主要包括三大块：模型权重本身、KV Cache、以及推理过程中的临时激活值。其中 KV Cache 随上下文长度线性增长，通常是长文本场景下的最大瓶颈。</p></div><p>KV Cache 是推理显存的最大开销来源之一。以一个典型的 7B 模型为例：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>模型：7B 参数，32 层，32 个注意力头，每个头维度 128（dim_head=128）</span></span>
<span class="line"><span>      → 每层 K 的维度 = 32 × 128 = 4096</span></span>
<span class="line"><span>      → 每层 V 的维度 = 32 × 128 = 4096</span></span>
<span class="line"><span>      → 每层 KV = 2 × 4096 = 8192 个元素</span></span>
<span class="line"><span>      → 每个元素在 FP16 下占 2 字节</span></span>
<span class="line"><span></span></span>
<span class="line"><span>单个 token 的 KV Cache 大小：</span></span>
<span class="line"><span>  32 层 × 8192 元素 × 2 字节 = 524,288 字节 = 0.5 MB</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上下文长度 → KV Cache 总大小：</span></span>
<span class="line"><span>  1K tokens   = 0.5 GB</span></span>
<span class="line"><span>  4K tokens   = 2 GB</span></span>
<span class="line"><span>  32K tokens  = 16 GB</span></span>
<span class="line"><span>  128K tokens = 64 GB    ← 已经超过绝大多数 GPU 的显存！</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>这就是为什么长上下文推理如此昂贵——KV Cache 随上下文<strong>线性增长</strong>。<strong>在实际部署中，KV Cache 常常比模型权重本身占用更多显存。</strong></p><h3 id="_4-3-pagedattention-vllm-核心技术" tabindex="-1">4.3 PagedAttention（vLLM 核心技术） <a class="header-anchor" href="#_4-3-pagedattention-vllm-核心技术" aria-label="Permalink to “4.3 PagedAttention（vLLM 核心技术）”">​</a></h3><p>传统的 KV Cache 管理方式是为每个请求预分配一整块连续显存，就像给每个客人一张固定大小的餐桌，无论他吃多少：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>传统 KV Cache 管理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请求 A: 预分配 4K token 空间  [████████░░░░░░░░░░░░]  ← 大量碎片</span></span>
<span class="line"><span>请求 B: 预分配 4K token 空间  [████████████████░░░░]  ← 浪费</span></span>
<span class="line"><span>请求 C: 预分配 4K token 空间  [██░░░░░░░░░░░░░░░░░░]  ← 严重浪费</span></span>
<span class="line"><span></span></span>
<span class="line"><span>总分配 12GB，实际使用不到 6GB     → 显存利用率 ~50%</span></span>
<span class="line"><span>碎片化严重，难以支持大批量请求</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>PagedAttention</strong> 借鉴了操作系统中虚拟内存分页的思想——把 KV Cache 切分成固定大小的块（block/page），按需分配：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PagedAttention 的 KV Cache 管理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>物理块池（共 8 个 block）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Block 0  [████] ← 请求 A 占用</span></span>
<span class="line"><span>Block 1  [████] ← 请求 A 占用</span></span>
<span class="line"><span>Block 2  [████] ← 请求 B 占用</span></span>
<span class="line"><span>Block 3  [████] ← 请求 B 占用</span></span>
<span class="line"><span>Block 4  [████] ← 请求 C 占用</span></span>
<span class="line"><span>Block 5  [ 空 ] ← 空闲，任何请求需要时可分配</span></span>
<span class="line"><span>Block 6  [████] ← 请求 A 占用（A 的 block 不连续也没关系！）</span></span>
<span class="line"><span>Block 7  [████] ← 请求 B 占用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>逻辑到物理映射：</span></span>
<span class="line"><span>  请求 A 的逻辑块 [0,1,2] → 物理块 [0,1,6]   ← 通过页表映射</span></span>
<span class="line"><span>  请求 B 的逻辑块 [0,1,2] → 物理块 [2,3,7]</span></span>
<span class="line"><span>  请求 C 的逻辑块 [0]     → 物理块 [4]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>显存利用率：从 ~50% 提升到接近 100%</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p><strong>PagedAttention 的三大优势</strong>：</p><ol><li><strong>零浪费</strong>：按需分配，不会预留未使用的空间</li><li><strong>灵活共享</strong>：多个请求可以共享同一物理块（如相同的 system prompt）</li><li><strong>更高吞吐</strong>：同样的显存可以服务 2-4 倍的并发请求</li></ol><p>这正是 vLLM 能够实现高吞吐推理的核心原因。</p><h2 id="_5-streaming-流式输出" tabindex="-1">5. Streaming（流式输出） <a class="header-anchor" href="#_5-streaming-流式输出" aria-label="Permalink to “5. Streaming（流式输出）”">​</a></h2><p>流式输出是指模型<strong>生成一个 token 就立即返回一个 token</strong>，而不是等全部生成完毕再一次性返回：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>非流式 vs 流式：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>非流式（Batch）：</span></span>
<span class="line"><span>  用户发送请求 ────────────────────────────────→ 等待 5 秒 ──→ 一次性收到全部回复</span></span>
<span class="line"><span>                  模型内部生成 token1, token2, ..., token200</span></span>
<span class="line"><span></span></span>
<span class="line"><span>流式（Streaming）：</span></span>
<span class="line"><span>  用户发送请求 → 等 0.5s → &quot;我&quot; → &quot;很&quot; → &quot;高&quot; → &quot;兴&quot; → ... → &quot;！&quot;</span></span>
<span class="line"><span>                 ↑           每个 token 逐个到达，用户可以边看边等</span></span>
<span class="line"><span>                 TTFT ↓</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><strong>流式输出的意义</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>非流式</th><th>流式</th></tr></thead><tbody><tr><td>用户感知延迟</td><td>高（等到全部完成）</td><td>低（TTFT 后才开始有文字）</td></tr><tr><td>可中断性</td><td>差</td><td>好（看到不对劲可以提前停止）</td></tr><tr><td>交互体验</td><td>像等一封邮件</td><td>像在和人聊天</td></tr><tr><td>实现复杂度</td><td>低</td><td>需要 SSE/WebSocket</td></tr></tbody></table><p>OpenAI 的 API 使用 <strong>Server-Sent Events（SSE）</strong> 实现流式输出，每个事件包含一个 delta（增量 token）。</p><h2 id="_6-speculative-decoding-推测解码" tabindex="-1">6. Speculative Decoding（推测解码） <a class="header-anchor" href="#_6-speculative-decoding-推测解码" aria-label="Permalink to “6. Speculative Decoding（推测解码）”">​</a></h2><p>推测解码是一种&quot;用速度换正确性&quot;的推理加速技术。核心思想很简单：<strong>让小模型（草稿模型）快速生成多个候选 token，大模型（目标模型）一次性验证这些 token 是否正确</strong>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>推测解码流水线：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      Draft Model（草稿模型，如 0.5B 小模型）</span></span>
<span class="line"><span>      │  速度极快，但准确率不如大模型</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>  推测生成: [&quot;我&quot;, &quot;认为&quot;, &quot;这&quot;, &quot;是&quot;, &quot;一&quot;, &quot;个&quot;, &quot;好&quot;, &quot;主意&quot;]</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>      Target Model（目标模型，如 70B 大模型）</span></span>
<span class="line"><span>      │  一次前向传播，同时验证全部 8 个 token</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>      ┌─────────────────────────────────────┐</span></span>
<span class="line"><span>      │ Token  &quot;我&quot; &quot;认为&quot; &quot;这&quot; &quot;是&quot; &quot;一&quot; &quot;个&quot; &quot;好&quot; &quot;主意&quot; │</span></span>
<span class="line"><span>      │ 小模型  ✓    ✓     ✓    ✓    ✓    ✓    ✗    ✗     │</span></span>
<span class="line"><span>      │ 大模型  ✓    ✓     ✓    ✓    ✓    ✓    ✓    ?     │</span></span>
<span class="line"><span>      │                                                     │</span></span>
<span class="line"><span>      │ 小模型在&quot;个&quot;之后预测&quot;好&quot;，大模型认为应该是&quot;非常好&quot;  │</span></span>
<span class="line"><span>      │ 接受前 6 个 token (✓)，拒绝第 7 个 (✗)              │</span></span>
<span class="line"><span>      └─────────────────────────────────────┘</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>  一次大模型前向传播 → 确认了 6 个 token，相当于吞吐量提升 6 倍</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p><strong>关键前提——为什么这能加速？</strong></p><p>大模型一次处理 8 个 token 的时间 ≈ 处理 1 个 token 的时间。这得益于 Transformer 的并行特性：attention 计算中，所有 token 的关注度矩阵是并行计算的。所以<strong>一次验证 N 个 token 和一次生成 1 个 token 的时间几乎相同</strong>。</p><p><strong>适用条件</strong>：</p><ol><li>草稿模型需要和目标模型使用相同的 tokenizer</li><li>草稿模型需要足够小（通常为目标模型的 1/10 到 1/100 参数量）</li><li>草稿模型的预测准确率不能太低，否则大量 token 被拒绝，加速效果有限</li></ol><p><strong>实际效果</strong>：在代码生成、翻译等&quot;确定性较强&quot;的任务上，推测解码可以实现 <strong>2-3 倍的推理加速</strong>，且生成的文本与原始大模型完全一致（因为最终由大模型验证）。</p><h2 id="_7-推理性能指标" tabindex="-1">7. 推理性能指标 <a class="header-anchor" href="#_7-推理性能指标" aria-label="Permalink to “7. 推理性能指标”">​</a></h2><p>理解推理性能指标，才能科学地评估和优化推理系统。</p><h3 id="_7-1-ttft-time-to-first-token" tabindex="-1">7.1 TTFT（Time to First Token） <a class="header-anchor" href="#_7-1-ttft-time-to-first-token" aria-label="Permalink to “7.1 TTFT（Time to First Token）”">​</a></h3><p>从用户发送请求到收到第一个 token 的时间间隔:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TTFT 的组成：</span></span>
<span class="line"><span>  用户点击发送 → 网络传输 → 请求排队 → Prefill（预填充）→ 网络返回第一个 token</span></span>
<span class="line"><span>  │                                                                            │</span></span>
<span class="line"><span>  └──────────────────────── TTFT 通常 200ms ~ 2s ─────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Prefill 阶段：把所有输入 token 一次性送进模型，计算并填充 KV Cache</span></span>
<span class="line"><span>  → 这是 TTFT 中最耗时的部分</span></span>
<span class="line"><span>  → 输入越长，Prefill 越慢</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">TTFT 为什么重要？</p><p>这是用户感知中的&quot;响应速度&quot;。就像点外卖时从下单到第一个骑手接单的时间——TTFT 越小，用户越不焦虑。通常目标：</p><ul><li>好的体验：TTFT &lt; 500ms</li><li>可接受：500ms ~ 2s</li><li>需要优化：&gt; 2s</li></ul></div><h3 id="_7-2-tpot-time-per-output-token" tabindex="-1">7.2 TPOT（Time per Output Token） <a class="header-anchor" href="#_7-2-tpot-time-per-output-token" aria-label="Permalink to “7.2 TPOT（Time per Output Token）”">​</a></h3><p>在生成阶段，每输出一个 token 的平均时间。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TPOT 决定了输出速度：</span></span>
<span class="line"><span>  TPOT 50ms  → 每秒 20 tokens → 就像普通人说话的速度</span></span>
<span class="line"><span>  TPOT 20ms  → 每秒 50 tokens → 快速阅读的速度</span></span>
<span class="line"><span>  TPOT 10ms  → 每秒 100 tokens → 极速输出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TPOT = (总生成时间) / (生成的 token 数)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>TPOT 受 KV Cache 大小影响</strong>：上下文越长，每次 Attention 计算的开销越大，TPOT 越高。</p><h3 id="_7-3-throughput-吞吐量-与-qps" tabindex="-1">7.3 Throughput（吞吐量）与 QPS <a class="header-anchor" href="#_7-3-throughput-吞吐量-与-qps" aria-label="Permalink to “7.3 Throughput（吞吐量）与 QPS”">​</a></h3><p><strong>吞吐量</strong>是系统整体每秒可以处理多少请求或生成多少 token。在生产环境中，吞吐量通常用 <strong>QPS（Queries Per Second，每秒查询数）</strong> 来衡量，两者密切相关但视角不同：</p><table tabindex="0"><thead><tr><th></th><th>Throughput（吞吐量）</th><th>QPS（每秒查询数）</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>每秒处理的 token 总量</td><td>每秒完成的请求数量</td></tr><tr><td><strong>单位</strong></td><td>tokens/s</td><td>请求/s</td></tr><tr><td><strong>关注点</strong></td><td>系统算力利用效率</td><td>用户感知的服务能力</td></tr><tr><td><strong>关系</strong></td><td>吞吐量 tokens/s = QPS × 平均每个请求的 token 数</td><td>QPS = 吞吐量 / 平均每个请求的 token 数</td></tr></tbody></table><p><strong>计算示例</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>场景 A：短回答（平均每个请求 20 token）</span></span>
<span class="line"><span>  系统吞吐量 = 1000 tokens/s</span></span>
<span class="line"><span>  → QPS = 1000 / 20 = 50 请求/s</span></span>
<span class="line"><span>  → 服务能力：每秒 50 个用户</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景 B：长回答（平均每个请求 200 token）</span></span>
<span class="line"><span>  系统吞吐量 = 1000 tokens/s</span></span>
<span class="line"><span>  → QPS = 1000 / 200 = 5 请求/s</span></span>
<span class="line"><span>  → 服务能力：每秒仅 5 个用户</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">关键洞察</p><p>同样的吞吐量，长回答场景下的 QPS 会急剧下降。</p><p>这就是为什么评估 LLM 服务性能时，不能只看 QPS——一个系统可能在简单问候场景下 QPS 很高，但在生成长文档时 QPS 骤降。</p><p>吞吐量（tokens/s）才是更稳定的衡量标准。</p></div><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>吞吐量 = 并发请求数 / 平均每请求完成时间</span></span>
<span class="line"><span></span></span>
<span class="line"><span>或：吞吐量 = 每秒处理的总 token 数（含输入和输出）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高吞吐示例：</span></span>
<span class="line"><span>  10 个请求并发，每个请求生成 100 token</span></span>
<span class="line"><span>  总时间 5 秒</span></span>
<span class="line"><span>  → 吞吐量 = 10 × 100 / 5 = 200 tokens/s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>TTFT、TPOT、Throughput 三者之间的关系</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>                    TTFT ↓            TPOT ↓</span></span>
<span class="line"><span>                      ↓                 ↓</span></span>
<span class="line"><span>  用户请求 → [Prefill] → [Generate: token₁ → token₂ → ... → token_N] → 完成</span></span>
<span class="line"><span>                      ↑                                   ↑</span></span>
<span class="line"><span>                  受输入长度                       受 KV Cache 大小</span></span>
<span class="line"><span>                  和模型大小影响                    和并发请求数影响</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  吞吐量 = f(模型并行策略, 批处理大小, 显存带宽, GPU 数量)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>优化优先级因场景而异</strong>：</p><ul><li><strong>聊天机器人</strong>：TTFT 最关键（用户等待首个字的耐心有限）</li><li><strong>批量文本处理</strong>：吞吐量最关键（不关心单次延迟，关心整体效率）</li><li><strong>实时翻译</strong>：TPOT 最关键（不能出现断续感）</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>定义</th><th>优化方向</th><th>典型目标</th></tr></thead><tbody><tr><td>TTFT</td><td>首 token 延迟</td><td>减小 Prefill 时间、提升 GPU 利用率</td><td>&lt; 500ms</td></tr><tr><td>TPOT</td><td>每 token 生成时间</td><td>减小 KV Cache 计算开销</td><td>&lt; 50ms</td></tr><tr><td>Throughput</td><td>系统整体吞吐</td><td>Continuous Batching、PagedAttention</td><td>依赖场景</td></tr></tbody></table>`,49))]))}});export{T as __pageData,f as default};
